<template><view class="page"><text class="title">未来职业探索墙</text><text class="subtitle">现在，自己去找找你感兴趣了解的职业。</text><view v-for="item in categories" :key="item.categoryId" class="card" hover-class="card-hover" @click="open(item)"><view><text class="category-name">{{item.name}}</text><text class="category-count">{{item.explorableCount}} 个职业</text></view><text v-if="item.viewed" class="viewed">已查看</text></view><text class="tip">点击职业大类进一步了解具体职业卡片信息</text><text v-if="readOnly" class="readonly-tip">本次探索已完成，当前内容仅可查看</text></view></template>
<script>
import { getCatalog, getRecord, userMessage } from '@/api/zycck'
export default { data: () => ({ recordId: '', instanceId: '', gameId: '', categories: [], readOnly: false }), onLoad(o) { Object.assign(this, { recordId: o.recordId || '', instanceId: o.instanceId || '', gameId: o.gameId || '', readOnly: o.readOnly === '1' }); this.load() }, methods: { async load() { try { const r = await getCatalog({ instanceId: this.instanceId, gameId: this.gameId }); const d = r.data || {}; const rows = d.careers || []; let viewed = []; if (this.recordId) { try { const rr = await getRecord(this.recordId); const raw = rr.data && ((rr.data.record && rr.data.record.viewedCareerIds) || rr.data.viewedCareerIds); viewed = Array.isArray(raw) ? raw : JSON.parse(raw || '[]') } catch (e) {} } this.categories = (d.categories || []).map(c => { const inCategory = rows.filter(q => String(q.categoryId) === String(c.categoryId) && String(q.hasQuestion) !== '1'); return { ...c, explorableCount: inCategory.length, viewed: inCategory.some(q => viewed.some(id => String(id) === String(q.careerQuestionId || q.careerId))) } }) } catch (e) { uni.showToast({ title: userMessage(e, '职业分类加载失败，请重试'), icon: 'none' }) } }, open(item) { uni.navigateTo({ url: `/pages/zycck/careers?recordId=${this.recordId}&instanceId=${this.instanceId}&gameId=${this.gameId}&categoryId=${item.categoryId}&readOnly=${this.readOnly ? '1' : '0'}` }) } } }
</script>
<style scoped>.page{padding:48rpx 36rpx;background:#f5f7fb;min-height:100vh;box-sizing:border-box;display:flex;flex-direction:column;justify-content:center;animation:pageIn .35s ease-out}.title{display:block;font-size:50rpx;font-weight:800;text-align:center;color:#1a2c4a}.subtitle{display:block;text-align:center;color:#64748b;margin:16rpx 0 30rpx}.card{display:flex;align-items:center;justify-content:space-between;background:#fff;padding:34rpx 28rpx;margin:14rpx 0;border-radius:16rpx;color:#243b53;box-shadow:0 6rpx 18rpx rgba(31,41,55,.04)}.card-hover{background:#edf4ff;transform:scale(.985)}.category-name,.category-count{display:block}.category-name{font-size:32rpx;font-weight:700}.category-count{margin-top:10rpx;color:#8a94a6;font-size:25rpx}.viewed{color:#42a868;font-size:25rpx}.tip,.readonly-tip{display:block;text-align:center;color:#8a94a6;font-size:24rpx;margin-top:26rpx}.readonly-tip{color:#d97745;margin-top:12rpx}@keyframes pageIn{from{opacity:0;transform:translateY(18rpx)}to{opacity:1;transform:translateY(0)}}</style>
